package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamFirstAidBank1 {
    private const val T = "ප්‍රථමාධාර, හදිසි අනතුරු හා ක්‍රීඩා ආබාධ කළමනාකරණය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("හදිසි අනතුරක් හෝ රෝගී තත්ත්වයක් ඇති වූ වහාම වෛද්‍ය ආධාර ලැබෙන තෙක් රෝගියාට ලබාදෙන මූලික උපකාරය හඳුන්වන්නේ කෙසේද?", "ප්‍රථමාධාර (First Aid)", "වෛද්‍ය ප්‍රතිකාර", "ශල්‍යකර්ම", "පුනරුත්ථාපනය", "ප්‍රථමාධාර යනු සුදුසුකම් ලත් වෛද්‍ය ප්‍රතිකාර ලැබෙන තෙක් ජීවිතය බේරා ගැනීමට ලබාදෙන තාවකාලික සත්කාරයයි."),
        q("ප්‍රථමාධාර ලබාදීමේ ප්‍රමුඛතම සහ මූලිකම පරමාර්ථය කුමක්ද?", "රෝගියාගේ ජීවිතය ආරක්ෂා කර ගැනීම (Preserve Life)", "තුවාල පරීක්ෂා කිරීම", "ඖෂධ නියම කිරීම", "රෝග විනිශ්චය කිරීම", "ප්‍රථමාධාරයේ ප්‍රධාන අරමුණු තුන (3Ps) නම් ජීවිතය රැකීම, තත්ත්වය නරක අතට හැරීම වැළැක්වීම සහ සුවය ඉක්මන් කිරීමයි."),
        q("හදිසි අනතුරු අවස්ථාවකදී ප්‍රාථමික සමීක්ෂණයේ (Primary Survey) පියවර අනුපිළිවෙළ නිරූපණය කරන DRABC හි D අකුරෙන් අදහස් වන්නේ කුමක්ද?", "අනතුර හෙවත් පරිසරයේ ආරක්ෂාව තහවුරු කර ගැනීම (Danger)", "ඖෂධ දීම (Drugs)", "රෝගියා සෙලවීම (Disturb)", "තුවාල පරීක්ෂාව (Damage)", "ප්‍රථමාධාරකරු මුලින්ම තමාට, රෝගියාට සහ අවට සිටින අයට අවදානමක් නැති බවට ආරක්ෂාව තහවුරු කරගත යුතුය."),
        q("ප්‍රාථමික සමීක්ෂණයේ DRABC ක්‍රියාවලියේ R අකුරෙන් නියෝජනය වන ක්‍රියාමාර්ගය කුමක්ද?", "රෝගියාගේ ප්‍රතිචාරය හෙවත් සිහිසුන් බව පරීක්ෂා කිරීම (Response)", "හුස්ම ගැනීම පරීක්ෂාව", "රුධිර පීඩනය බැලීම", "තුවාල බැඳීම", "රෝගියාගේ උරහිස් මෘදු ලෙස තට්ටු කර කතා කරමින් සිහිය තිබේදැයි ප්‍රතිචාරය විමසිය යුතුය."),
        q("DRABC හි A අකුරෙන් විස්තර කෙරෙන මූලික පියවර කුමක්ද?", "ශ්වාසනාලය විවෘත කිරීම හෙවත් ශ්වසන මාර්ගය පරීක්ෂා කිරීම (Airway)", "අත් පා චලනය", "ඇඳුම් ලිහිල් කිරීම", "ඖෂධ බීම", "හිස පිටුපසට ඇල කර නිකට එසවීමෙන් (Head-tilt chin-lift) ශ්වසන මාර්ගය විවෘත කෙරේ."),
        q("DRABC හි B අකුරෙන් අදහස් වන්නේ රෝගියාගේ කුමන තත්ත්වය පරීක්ෂා කිරීමද?", "හුස්ම ගැනීම සාමාන්‍ය ලෙස සිදුවේදැයි පරීක්ෂා කිරීම (Breathing)", "ශරීර උෂ්ණත්වය බැලීම", "ලේ ගැලීම පරීක්ෂාව", "ඇටකටු බිඳී ඇත්දැයි බැලීම", "තත්පර 10ක් ඇතුළත රෝගියා සාමාන්‍ය ලෙස හුස්ම ගන්නේදැයි බැලීම, ඇසීම හා දැනීම මගින් තහවුරු කරයි."),
        q("DRABC හි C අකුරෙන් නිරූපණය වන මූලික පියවර කුමක්ද?", "රුධිර සංසරණය පරීක්ෂා කිරීම සහ පපුව තෙරපීම (Circulation / Compressions)", "සිහිය ලැබීම", "සීතල පාලනය", "සන්ධි පරීක්ෂාව", "ස්පන්දනය සහ රුධිර සංසරණය නැති විට වහාම පපුව තෙරපීම මගින් CPR ඇරඹිය යුතුය."),
        q("සිහිසුන්ව සිටින නමුත් සාමාන්‍ය පරිදි හුස්ම ගන්නා රෝගියෙකු තැබිය යුතු වඩාත් සුදුසු ඉරියව්ව කුමක්ද?", "සෝදිසි ඉරියව්ව හෙවත් සුවය ලැබීමේ ඉරියව්ව (Recovery Position)", "උඩුබැලි අතට තැබීම", "වාඩි කරවීම", "මුණින්තලා කර තැබීම", "සෝදිසි ඉරියව්වේදී දිව ගිලී ශ්වසන මාර්ගය අවහිර වීම වැළකෙන අතර වමනය ගියහොත් පිටතට ගලා යයි."),
        q("හෘද ස්පන්දනය හා හුස්ම ගැනීම නැවතුණු වැඩිහිටි රෝගියෙකුට ලබාදෙන CPR ක්‍රියාවලියේ පපුව තෙරපීම් සහ මුඛයෙන් හුස්ම දීම් අතර අනුපාතය කොපමණද?", "පපුව තෙරපීම් 30කට කෘත්‍රිම හුස්ම වාර 2ක් (30 — 2 අනුපාතය)", "තෙරපීම් 15කට හුස්ම 1ක්", "තෙරපීම් 50කට හුස්ම 5ක්", "තෙරපීම් 10කට හුස්ම 2ක්", "සම්මත CPR ක්‍රියාවලියේදී අඛණ්ඩව පපුව 30 වතාවක් තෙරපා හුස්ම වාර 2ක් ලබාදිය යුතුය."),
        q("වැඩිහිටියෙකුට CPR ලබාදීමේදී පපුව තෙරපිය යුතු නිවැරදි වේගය (Rate) විනාඩියකට වාර කීයක්ද?", "විනාඩියකට වාර 100 සිට 120 දක්වා වේගයකින්", "විනාඩියකට වාර 60ක්", "විනාඩියකට වාර 80ක්", "විනාඩියකට වාර 150ක්", "පපුව කාර්යක්ෂමව රුධිරය පොම්ප කිරීමට විනාඩියකට වාර 100-120 අතර ස්ථාවර රිද්මයකින් තෙරපිය යුතුය."),
        q("වැඩිහිටි රෝගියෙකුට CPR ලබාදීමේදී පපුව පහළට එබිය යුතු (Depth) සම්මත ගැඹුර කොපමණද?", "සෙන්ටිමීටර 5 සිට 6 දක්වා (අඟල් 2 සිට 2.5 දක්වා)", "සෙන්ටිමීටර 2ක් පමණි", "සෙන්ටිමීටර 10ක්", "සෙන්ටිමීටර 1ක් පමණි", "හෘදය සම්පීඩනය වීමට වැඩිහිටියෙකුගේ පපුව සෙන්ටිමීටර 5-6ක් ගැඹුරට තද කළ යුතුය."),
        q("හදිසි හෘදයාබාධයකදී ස්වයංක්‍රීයව හෘද රිද්මය පරීක්ෂා කර විද්‍යුත් කම්පනයක් ලබාදෙන උපකරණය කුමක්ද?", "ස්වයංක්‍රීය බාහිර හෘද කම්පන යන්ත්‍රය (AED)", "ECG යන්ත්‍රය", "එක්ස් කිරණ යන්ත්‍රය", "ඔක්සිජන් සිලින්ඩරය", "AED (Automated External Defibrillator) මගින් හෘද පේශිවල අක්‍රමවත් ගැස්ම නිවැරදි කරයි."),
        q("මාස 1 සිට අවුරුදු 1 දක්වා ළදරුවෙකුට CPR ලබාදීමේදී පපුව තෙරපීම සඳහා යොදා ගත යුත්තේ කුමක්ද?", "ඇඟිලි තුඩු දෙකක් පමණි (Two fingers)", "දෑත් දෙකම එකට තබා", "අත්ල පමණක් තබා", "වැළමිටෙන් තද කර", "ළදරුවාගේ ඉළඇට සියුම් බැවින් මැදඟිල්ල සහ වෙදඟිල්ල පමණක් භාවිතයෙන් සෙ.මී. 4ක් ගැඹුරට තෙරපයි."),
        q("ක්‍රීඩාවකදී හෝ අනතුරකදී සන්ධියක් සම්බන්ධ කරන බන්ධනියක් (Ligament) අධික ලෙස ඇදීම හෝ ඉරී යාම හඳුන්වන්නේ කෙසේද?", "උළුක්කුවක් හෙවත් පෙරළීමක් (Sprain)", "පේශි ඇදීමක්", "අස්ථි බිඳීමක්", "සන්ධි පැනීමක්", "අස්ථි දෙකක් එකිනෙක බඳින බන්ධනී (Ligaments) තුවාල වීම උළුක්කුවක් (Sprain) වේ."),
        q("ක්‍රීඩාවකදී පේශියක් (Muscle) හෝ කණ්ඩරාවක් (Tendon) අධික ආතතිය නිසා ඇදීම හෝ ඉරී යාම හඳුන්වන්නේ කෙසේද?", "පේශි ඇදීමක් හෙවත් පිපිරීමක් (Strain)", "උළුක්කුවක්", "සන්ධි ගෙවීමක්", "අස්ථි බිඳීමක්", "පේශි හෝ කණ්ඩරා තුවාල වීම Strain ලෙස හඳුන්වනු ලැබේ."),
        q("උග්‍ර මෘදු පටක ආබාධයකදී (උළුක්කු හා පේශි ඇදීම්) මුල් පැය 48 තුළ පිළිපැදිය යුතු සම්මත ප්‍රතිකාර ක්‍රමය කුමක්ද?", "R.I.C.E. ප්‍රතිකාර ක්‍රමය", "උණුසුම් ජලයෙන් තැවීම", "තදින් සම්බාහනය කිරීම", "දිගටම ක්‍රීඩා කිරීම", "Rest (විවේකය), Ice (අයිස් තැබීම), Compression (පීඩන වෙළුම), Elevation (එසවීම) අනුගමනය කළ යුතුය."),
        q("R.I.C.E. ක්‍රමයේ R අකුරෙන් අදහස් වන විවේකය (Rest) ලබාදීමේ ප්‍රධාන අරමුණ කුමක්ද?", "තුවාල වූ පටකයට තවදුරටත් හානි වීම වැළැක්වීම", "ශරීරය සිසිල් කිරීම", "රුධිර පීඩනය වැඩි කිරීම", "මාංශ පේශි වර්ධනය", "තුවාල වූ අවයවය වහාම චලනයෙන් වළක්වා විවේක ගැන්වීමෙන් අභ්‍යන්තර ලේ ගැලීම පාලනය වේ."),
        q("R.I.C.E. ක්‍රමයේදී අයිස් තැබීම (Ice) පිළිබඳ නිවැරදි මාර්ගෝපදේශය කුමක්ද?", "වරකට විනාඩි 15-20ක් රෙදි කඩක ඔතා තැබිය යුතු අතර සම මත සෘජුව නොතැබිය යුතුය", "පැය ගණනාවක් නොකඩවා තැබීම", "අයිස් කෙළින්ම සම මත අතුල්ලා තැබීම", "උණුසුම් වතුර සමග මිශ්‍ර කර දැමීම", "සෘජුව අයිස් තැබීමෙන් හිම පිළිස්සුම් (Ice burns) ඇතිවිය හැකි බැවින් තුවායක ඔතා තැබිය යුතුය."),
        q("R.I.C.E. ප්‍රතිකාරයේ C අකුරෙන් දැක්වෙන සම්පීඩනය (Compression) මගින් ඉටුවන ප්‍රධාන කාර්යය කුමක්ද?", "ඉදිමීම පාලනය කිරීම සහ පටකවලට ආධාරකයක් සැපයීම", "අස්ථි එකතු කිරීම", "උෂ්ණත්වය ඉහළ දැමීම", "ස්නායු උත්තේජනය", "ක්‍රේප් වෙළුම් පටියක් (Crepe bandage) මගින් මධ්‍යස්ථ පීඩනයක් යොදා ඉදිමීම සීමා කෙරේ."),
        q("R.I.C.E. ක්‍රමයේ E අකුරෙන් දැක්වෙන එසවීම (Elevation) මගින් ලබාගන්නා වාසිය කුමක්ද?", "ගුරුත්වාකර්ෂණය නිසා තුවාල වූ ස්ථානයට රුධිරය හා තරල එක්රැස් වීම අවම වී ඉදිමීම අඩුවීම", "රුධිර ගමනාගමනය සම්පූර්ණයෙන්ම නැවතීම", "පේශි තද වීම", "වේදනාව සම්පූර්ණයෙන් නැතිවීම", "තුවාල වූ අවයවය හෘදයේ මට්ටමට වඩා ඉහළින් ඔසවා තැබීමෙන් සිරෝස් තරල හා රුධිර එකතු වීම අඩු වේ."),
        q("මෘදු පටක ආබාධයකදී මුල් පැය 48-72 තුළ වැළකී සිටිය යුතු අහිතකර සාධක දක්වන H.A.R.M. හි H අකුර කුමක්ද?", "තාපය හෙවත් රස්නය යෙදීම (Heat)", "විවේකය (Health)", "රෝහල්ගත කිරීම (Hospital)", "හයිඩ්‍රජන් (Hydrogen)", "මුල් පැය 48 තුළ රස්නය යෙදීමෙන් (Heat) රුධිර වාහිනී ප්‍රසාරණය වී ඉදිමීම හා ලේ ගැලීම වැඩි වේ."),
        q("H.A.R.M. හි A අකුරෙන් නියෝජනය වන වැළකිය යුතු සාධකය කුමක්ද?", "මත්පැන් භාවිතය (Alcohol)", "ඇස්ප්‍රින් ගැනීම", "ඇවිදීම", "අයිස් තැබීම", "මත්පැන් රුධිර නාල ප්‍රසාරණය කර ඉදිමීම වැඩි කරන අතර වේදනාව හඳුනා ගැනීම අවුල් කරයි."),
        q("H.A.R.M. හි R අකුරෙන් වැළකී සිටිය යුතු කුමන ක්‍රියාව විස්තර කෙරේද?", "දුවීම හෙවත් නැවත ක්‍රීඩා කිරීම (Running / Exercise)", "විවේක ගැනීම", "වෛද්‍යවරයා හමුවීම", "හුස්ම ගැනීම", "තුවාලය සුව වීමට පෙර දුවීම හෝ ව්‍යායාම කිරීමෙන් තුවාලය වඩාත් බරපතළ වේ."),
        q("H.A.R.M. හි M අකුරෙන් දැක්වෙන මුල් අවධියේ නොකළ යුතු භයානක ක්‍රියාව කුමක්ද?", "සම්බාහනය කිරීම (Massage)", "ඖෂධ ගැනීම (Medicine)", "මිනුම් ගැනීම", "චලනය නැවැත්වීම", "මුල් පැය 72 තුළ තුවාල වූ ස්ථානය තදින් සම්බාහනය කිරීමෙන් අභ්‍යන්තර රුධිර වහනය තීව්‍ර වේ."),
        q("සන්ධියක් සෑදෙන අස්ථි අග්‍ර ඒවායේ සාමාන්‍ය පිහිටުމෙන් සම්පූර්ණයෙන්ම ඉවතට පැනීම හඳුන්වන්නේ කුමන නමකින්ද?", "සන්ධි පැනීම හෙවත් විස්ථාපනය (Dislocation)", "අස්ථි බිඳීම", "පේශි පෙරළීම", "ඉරිතැලීම", "උරහිස, ඇඟිලි හෝ වැළමිට සන්ධි පැනීමේදී දැඩි වේදනාවක් හා විකෘති හැඩයක් හටගනී."),
        q("ක්‍රීඩකයෙකුගේ සන්ධියක් පැන ඇති විට (Dislocation) ප්‍රථමාධාරකරු කිසිසේත්ම නොකළ යුත්තේ කුමක්ද?", "සන්ධිය බලහත්කාරයෙන් ආපසු යථා තත්ත්වයට පත් කිරීමට උත්සාහ කිරීම", "සන්ධිය අක්‍රිය කිරීම", "අයිස් තැබීම", "රෝහලට රැගෙන යාම", "අනවශ්‍ය ලෙස සන්ධිය ඇදීමට යාමෙන් ස්නායු හා ප්‍රධාන රුධිර වාහිනී කැඩී බරපතළ හානි විය හැක."),
        q("ක්‍රීඩාවේදී හෝ අධික වෙහෙසකදී හදිසියේම සිදුවන වේදනාකාරී අනෛච්ඡික පේශි සංකෝචනය හඳුන්වන්නේ කෙසේද?", "පේශි පෙරළීම හෙවත් මස්පිඬු පෙරළීම (Muscle Cramp)", "අස්ථි බිඳීම", "උළුක්කුව", "සන්ධි පැනීම", "විජලනය, ලවණ ඌනතාව හෝ අධික තෙහෙට්ටුව නිසා මස්පිඬු දැඩිව පෙරළීම සිදුවේ."),
        q("පාපන්දු ක්‍රීඩකයෙකුගේ කෙණ්ඩ පෙරළුණු විට (Calf muscle cramp) ලබාදිය යුතු ක්ෂණික ප්‍රථමාධාරය කුමක්ද?", "පාදය දිග හැර පාදයේ ඇඟිලි දණහිස දෙසට සෙමෙන් නමා පේශිය දිග හැරීම (Stretching)", "පේශියට තදින් පහර දීම", "වහාම දුවන්නට සැලැස්වීම", "උණු වතුර පානයට දීම", "කෙණ්ඩ පේශිය සෙමෙන් ඇදීමකට (Gentle passive stretch) ලක් කර ජලය හා ලවණ ලබාදිය යුතුය."),
        q("අස්ථියක් බිඳී ගියද අවට සම සිදුරු නොවී පවතින අස්ථි බිඳීම් වර්ගය කුමක්ද?", "සරල හෙවත් සංවෘත අස්ථි බිඳීම (Closed / Simple Fracture)", "විවෘත අස්ථි බිඳීම", "සංකීර්ණ අස්ථි බිඳීම", "හරස් බිඳීම", "සම මතුපිට නොකැඩී අභ්‍යන්තරව පමණක් අස්ථිය කැඩී තිබීම සංවෘත බිඳීමකි."),
        q("කැඩුණු අස්ථියේ කොටසක් සම සිදුරු කරමින් පිටතට නෙරා එන හෝ ගැඹුරු තුවාලයක් සහිත අස්ථි බිඳීම කුමක්ද?", "විවෘත හෙවත් සංයුක්ත අස්ථි බිඳීම (Open / Compound Fracture)", "සංවෘත බිඳීම", "කොළ අතු බිඳීම", "ආතති බිඳීම", "විවෘත බිඳීමකදී ආසාදන (Infections) ඇතිවීමේ සහ අධික රුධිර වහනයක් සිදුවීමේ අවදානම ඉතා වැඩිය."),
        q("කුඩා දරුවන්ගේ අස්ථිවල නම්‍යශීලී බව නිසා සම්පූර්ණයෙන්ම වෙන් නොවී අමු අත්තක් මෙන් නැමී පැලී යන අස්ථි බිඳීම කුමක්ද?", "කොළ අතු බිඳීම හෙවත් ග්‍රීන්ස්ටික් බිඳීම (Greenstick Fracture)", "විවෘත බිඳීම", "කුඩු වූ බිඳීම", "ආතති බිඳීම", "ළමුන්ගේ අස්ථිවල කාබනික පදාර්ථ බහුල බැවින් සම්පූර්ණයෙන් නොකැඩී කොළ අතු බිඳීමක් හටගනී."),
        q("අස්ථි බිඳීමකදී ප්‍රථමාධාර ලබාදීමේ මූලිකම රීතිය කුමක්ද?", "කැඩුණු ස්ථානයට ඉහළින් හා පහළින් පිහිටි සන්ධි දෙකම නිශ්චල කිරීම (Immobilization)", "කැඩුණු අස්ථිය කෙළින් කිරීමට තද කිරීම", "රෝගියා වහාම ඇවිද්දවීම", "තෙල් ගල්වා අතගෑම", "අස්ථි කැබලි සෙලවීමෙන් මාංශ පේශි හා රුධිර වාහිනී කැපී යාම වැළැක්වීමට ආධාරක (Splints) යොදා නිශ්චල කරයි."),
        q("අස්ථි බිඳීමක් නිශ්චල කිරීම සඳහා යොදා ගන්නා ලෑලි පටි හෝ ආධාරක උපකරණ හඳුන්වන්නේ කෙසේද?", "දැවති හෙවත් ආධාරක පටි (Splints)", "ස්ටෙතස්කෝපය", "බැන්ඩේජය පමණි", "කටු", "සෙලවීම පාලනය කිරීම සඳහා සවිමත් දැවති (Splints) අස්ථිය දෙපස තබා බඳිනු ලැබේ."),
        q("අතේ පෙරබාහුවේ (Forearm) හෝ මැණික් කටුවේ අස්ථි බිඳීමකදී අත එල්ලා තැබීමට භාවිත කරන එල්ලනය කුමක්ද?", "විශාල අත් එල්ලනය (Broad Arm Sling)", "උස් අත් එල්ලනය", "කරපටි එල්ලනය", "දණහිස් එල්ලනය", "නවාගත් වැළමිට අංශක 90ක තබා අත පපුව මත රඳවන්නේ විශාල අත් එල්ලනයෙනි."),
        q("අකුජ අස්ථිය (Clavicle / Collarbone) බිඳීමකදී හෝ අත්ලෙන් ලේ ගලන විට අත ඉහළට ඔසවා තැබීමට භාවිත කරන එල්ලනය කුමක්ද?", "උස් අත් එල්ලනය හෙවත් ශාන්ත ජෝන් එල්ලනය (High Arm Sling / St. John Sling)", "විශාල අත් එල්ලනය", "කරපටි එල්ලනය", "පාද එල්ලනය", "ඇඟිලි තුඩු විරුද්ධ උරහිස දෙසට ඉහළින් සිටින සේ අත රඳවන්නේ උස් අත් එල්ලනය මගිනි."),
        q("ප්‍රථමාධාර වෙළුම් පටි ගැටගැසීමේදී සමතලා බව රැකෙන සහ පහසුවෙන් ලිහාගත හැකි ගැටය කුමක්ද?", "හතරැස් ගැටය හෙවත් රීෆ් ගැටය (Reef Knot)", "කැරකිලි ගැටය", "බෝල ගැටය", "තොණ්ඩුව", "හතරැස් ගැටය රෝගියාගේ සමට තද නොවී සමතලාව පවතින අතර පහසුවෙන් ලිහාගත හැක."),
        q("ධමනියක් (Artery) කැපී යාමෙන් සිදුවන රුධිර වහනය හඳුනාගත හැකි ප්‍රධාන ලක්ෂණය කුමක්ද?", "තද රතු පැහැති රුධිරය හෘද ස්පන්දනය සමග වේගයෙන් විදීම (Spurting bright red blood)", "කළු රතු ලේ සෙමෙන් ගලා ඒම", "ලේ බිංදු බිංදු පැමිණීම", "දුඹුරු පැහැති වීම", "ධමනි තුළ අධික පීඩනයක් ඇති බැවින් ඔක්සිජන් පිරි දීප්තිමත් රතු රුධිරය විදීමක් ලෙස පිටවේ."),
        q("ශිරාවක් (Vein) කැපී යාමෙන් සිදුවන රුධිර වහනය හඳුනාගන්නේ කෙසේද?", "අඳුරු රතු පැහැති රුධිරය ස්ථාවරව නොකඩවා ගලා ඒම (Steady dark red flow)", "දීප්තිමත් රතු ලේ විදීම", "ලේ බිංදු බිංදු කාන්දු වීම", "කහ පැහැති වීම", "ශිරා රුධිරය අඩු පීඩනයක් යටතේ අඳුරු රතු පැහැයෙන් එක දිගට ගලා යයි."),
        q("කේශනාලිකා (Capillaries) තුවාල වීමකදී රුධිරය වහනය වන ආකාරය කුමක්ද?", "තුවාලය මතුපිටින් ලේ බිංදු සෙමින් කාන්දු වීම (Oozing)", "පීඩනයෙන් විදීම", "අඛණ්ඩ දැවැන්ත ධාරාවක් ලෙස ගැලීම", "ලේ නොගැලීම", "සිහින් කේශනාලිකා තුවාල වූ විට මතුපිටින් සෙමෙන් ලේ කාන්දු වීම සිදුවේ."),
        q("දැඩි බාහිර රුධිර වහනයක් පාලනය කිරීම සඳහා භාවිත කළ යුතු වඩාත් කාර්යක්ෂම ප්‍රථම පියවර කුමක්ද?", "තුවාලය මත සෘජුව පීඩනය යෙදීම (Direct Pressure)", "අයිස් වතුර දැමීම", "තුවාලය සේදීම", "පවුඩර් දැමීම", "පිරිසිදු රෙදි කඩකින් හෝ වෙළුම් පටියකින් තුවාලය මත තදින් තද කර තැබීම ලේ නැවැත්වීමේ හොඳම ක්‍රමයයි."),
        q("අත් පා තුවාලයකදී ලේ ගැලීම පාලනයට සෘජු පීඩනයට අමතරව කළ හැකි සරල පියවර කුමක්ද?", "තුවාල වූ අවයවය හෘද මට්ටමට වඩා ඉහළට එසවීම (Elevation)", "අවයවය පහළට එල්ලා දැමීම", "උණුසුම් කිරීම", "තදින් සම්බාහනය කිරීම", "හෘද මට්ටමට වඩා එසවූ විට ගුරුත්වය නිසා තුවාලයට ඇති රුධිර පීඩනය අඩු වේ."),
        q("නහයෙන් ලේ ගලන (Epistaxis) පුද්ගලයෙකුට ලබාදිය යුතු නිවැරදි ප්‍රථමාධාරය කුමක්ද?", "හිස මඳක් ඉදිරියට නමා නාසයේ මෘදු කොටස විනාඩි 10-15ක් තද කර අල්ලා සිටීම", "හිස හොඳින් පිටුපසට ඇල කිරීම", "නාසයට උණු වතුර දැමීම", "වැතිරී සිටීමට සැලැස්වීම", "හිස පිටුපසට ඇල කළහොත් ලේ උගුරට ගොස් පෙණහලුවලට කාන්දු විය හැකි බැවින් හිස ඉදිරියට නැමිය යුතුය."),
        q("ශරීරයේ වැදගත් ඉන්ද්‍රියයන්ට ප්‍රමාණවත් රුධිර සංසරණයක් නොලැබී යාමෙන් හටගන්නා ජීවිත තර්ජනය කුමක්ද?", "කම්පනය හෙවත් ෂොක් තත්ත්වය (Shock)", "අංශභාගය", "මීමැස්මොරය", "උණ", "රුධිර පීඩනය පහත වැටී මොළය ඇතුළු අවයවවලට ඔක්සිජන් නොලැබී යාම කම්පනයයි."),
        q("අධික ලෙස රුධිරය හෝ ශරීර තරල අහිමි වීම නිසා ඇතිවන කම්පන වර්ගය හඳුන්වන්නේ කෙසේද?", "අඩු රුධිර පරිමා කම්පනය (Hypovolaemic Shock)", "ස්නායු කම්පනය", "හෘදජනක කම්පනය", "ආසාත්මිකතා කම්පනය", "දැඩි ලේ ගැලීම්, දරුණු පාචනය හෝ පිළිස්සුම්වලදී රුධිර පරිමාව අඩුවීමෙන් මෙය හටගනී."),
        q("කම්පනයට (Shock) පත් වූ රෝගියෙකුගේ ශරීරයේ දැකිය හැකි ප්‍රධාන බාහිර ලක්ෂණ මොනවාද?", "සම සුදුමැලි වීම, සීතල වීම සහ දහඩිය දැමීම (Pale, cold, clammy skin)", "සම රතු වී දැවීම", "නාඩි වේගය ඉතා අඩුවීම", "අධික උණ ගැනීම", "රුධිර වාහිනී හැකිළීම නිසා සම සුදුමැලි වී සීතල දහඩියෙන් තෙත් වේ."),
        q("කම්පනය වැළැක්වීම සඳහා රෝගියාගේ පාද පොළොවේ සිට සෙන්ටිමීටර කීයක් පමණ ඉහළට එසවිය යුතුද?", "සෙන්ටිමීටර 15 සිට 30 දක්වා (අඟල් 6 සිට 12 දක්වා)", "සෙන්ටිමීටර 2ක්", "සෙන්ටිමීටර 80ක්", "මීටරයක් ඉහළට", "දෙපා මඳක් එසවීමෙන් අත් පා වල ඇති රුධිරය මොළය සහ හෘදය දෙසට ගලා ඒමට උපකාරී වේ."),
        q("කම්පනයට පත් වූ හෝ සිහිසුන් රෝගියෙකුට කිසිසේත්ම නොකළ යුත්තේ කුමක්ද?", "කටින් කිසිදු දියරයක් හෝ ආහාරයක් ලබා නොදිය යුතුය", "බ්ලැන්කට්ටුවක් පොරවීම", "සුවපහසුව තැබීම", "ඇඳුම් ලිහිල් කිරීම", "සිහිය මඳ රෝගියෙකුට යමක් පෙවීමෙන් එය ශ්වාසනාලය තුළට ගොස් හුස්ම හිරවීම සිදුවිය හැක."),
        q("උණුසුම් දියර, තෙල් හෝ වාෂ්ප ශරීරයේ පතිත වීමෙන් සිදුවන තුවාල හඳුන්වන්නේ කෙසේද?", "තැම්බීම් හෙවත් තැවීම් (Scalds)", "වියළි පිළිස්සුම්", "විද්‍යුත් පිළිස්සුම්", "රසායනික පිළිස්සුම්", "දියර හෝ වාෂ්ප මගින් සිදුවන තාප හානි Scalds වේ."),
        q("ගින්නෙන් හෝ රස්නයෙන් පිළිස්සුණු (Burns) ස්ථානයකට ක්ෂණිකව ලබාදිය යුතු ප්‍රථමාධාරය කුමක්ද?", "අවම වශයෙන් විනාඩි 20ක් ගලා යන සාමාන්‍ය ඇල් ජලයෙන් සිසිල් කිරීම", "අයිස් කැට සෘජුව තැබීම", "දන්තාලේප හෝ තෙල් ආලේප කිරීම", "බිබිලි සියල්ල පිපිරවීම", "ගලා යන ඇල් ජලයෙන් සේදීමෙන් පටකවල උෂ්ණත්වය බැස ගොස් ගැඹුරු පිළිස්සීම වළකී."),
        q("පිළිස්සුම් තුවාලයක හටගන්නා දිය බිබිලි (Blisters) සම්බන්ධයෙන් ප්‍රථමාධාරකරු කළ යුත්තේ කුමක්ද?", "දිය බිබිලි කිසිසේත් නොබිඳ පිරිසිදු වියළි රෙදිකඩකින් ආවරණය කිරීම", "කටුවකින් විද දියර ඉවත් කිරීම", "තදින් අතුල්ලා පිස දැමීම", "ලුණු කුඩු දැමීම", "දිය බිබිලි යනු ආසාදනවලින් අභ්‍යන්තර පටක ආරක්ෂා කරන ස්වභාවික ආවරණයක් බැවින් ඒවා නොබිඳිය යුතුය."),
        q("ශරීරයේ පිළිස්සුණු මතුපිට ප්‍රමාණය ප්‍රතිශතයක් ලෙස ගණනය කිරීම සඳහා වෛද්‍ය විද්‍යාවේ භාවිත වන සම්මත ක්‍රමය කුමක්ද?", "නමයේ නීතිය (Rule of Nines)", "දහයේ නීතිය", "පහේ නීතිය", "අටේ නීතිය", "ශරීරයේ ප්‍රධාන කොටස් 9% බැගින් වූ ගුණාකාරවලට බෙදා පිළිස්සුම් ප්‍රමාණය ගණනය කිරීම නමයේ නීතියයි."),
        q("රසායනික ද්‍රව්‍යයක් ඇසට හෝ සමට වැටී පිළිස්සීමක් සිදුවූ විට ලබාදිය යුතු ක්ෂණික ප්‍රථමාධාරය කුමක්ද?", "අවම වශයෙන් විනාඩි 20ක්වත් පිරිසිදු ඇල් ජලයෙන් අඛණ්ඩව සෝදා හැරීම", "තෙල් ආලේප කිරීම", "රෙදි කඩකින් තදින් පිස දැමීම", "වහාම ඇස් තද කර පියා ගැනීම", "රසායනික ද්‍රව්‍ය තනුක කර සෝදා හැරීමට ගලා යන ඇල් ජලයෙන් විනාඩි 20ක්වත් සේදිය යුතුය."),
        q("විදුලි සැර වැදුණු (Electric Shock) පුද්ගලයෙකුට ප්‍රථමාධාර ලබාදීමට පෙර ප්‍රථමාධාරකරු මුලින්ම කළ යුත්තේ කුමක්ද?", "ප්‍රධාන විදුලි ස්විචය විසන්ධි කිරීම හෝ වියළි ලී කැබැල්ලකින් වයරය ඈත් කිරීම", "රෝගියා අතින් ඇද ඉවත් කිරීම", "රෝගියාට වතුර ගැසීම", "රෝගියා බදාගෙන බිම පෙරළීම", "ප්‍රථමාධාරකරුගේ ආරක්ෂාව මුලින්ම තහවුරු කර විදුලි සැපයුම කපා හැරිය යුතුය."),
        q("ශ්‍රී ලංකාවේ උග්‍ර විෂ සහිත සර්පයන් අතරට අයත් වන රුධිර සංසරණ පද්ධතියට හා වකුගඩුවලට හානි කරන සර්පයා කවුරුන්ද?", "තිත් පොළඟා (Russell's Viper)", "නයා", "ගැරඬියා", "ඇහැටුල්ලා", "තිත් පොළඟාගේ විෂ හීමොටොක්සික් (Haemotoxic) වන අතර රුධිරය කැටි ගැසීම අවුල් කර වකුගඩු අකර්මණ්‍ය කරයි."),
        q("ශ්‍රී ලංකාවේ ස්නායු පද්ධතියට හානි කර ශ්වසනය අඩපණ කරවන උග්‍ර විෂ සහිත නාග කුලයේ සර්පයා කවුරුන්ද?", "නයා (Cobra)", "තිත් පොළඟා", "කුණකටුවා", "දිය නයා", "නයාගේ විෂ නියුරොටොක්සික් (Neurotoxic) වන අතර ස්නායු අඩපණ කර හුස්ම ගැනීම නවත්වයි."),
        q("නිවෙස් තුළ නිදා සිටින විට රාත්‍රී කාලයේ දෂ්ට කරන, දෂ්ට කළ ස්ථානයේ වේදනාවක් නොමැති උග්‍ර විෂ සහිත සර්පයා කවුරුන්ද?", "තෙල් කරවලා (Common Krait)", "තිත් පොළඟා", "නයා", "පොළොං තෙලිස්සා", "තෙල් කරවලාගේ දෂ්ටනය වේදනා රහිත වුවද දැඩි උදර වේදනාවක් සමග මාරාන්තික ස්නායු විෂ ශරීරගත වේ."),
        q("ශ්‍රී ලංකාවේ රෝහල්ගත වන වැඩිම සර්ප දෂ්ටන සංඛ්‍යාවකට වගකියන මධ්‍යස්ථ විෂ සහිත සර්පයා කවුරුන්ද?", "පොළොං තෙලිස්සා හෙවත් කුණකටුවා (Hump-nosed Viper)", "නයා", "තිත් පොළඟා", "මුදු කරවලා", "ශ්‍රී ලංකාවේ රෝහල් වාර්තාවල බහුලතම සර්ප දෂ්ටනය වන්නේ කුණකටු දෂ්ටනයයි."),
        q("සර්පයෙකු දෂ්ට කළ වහාම රෝගියා සම්බන්ධයෙන් අනුගමනය කළ යුතු අත්‍යවශ්‍යම පියවර කුමක්ද?", "රෝගියා බිය නොවී සන්සුන් කර දෂ්ට කළ අවයවය කිසිසේත් නොසොල්වා තැබීම", "රෝගියා ඉක්මනින් දුවවමින් රෝහලට ගෙන යාම", "දෂ්ට කළ තැන කැපීම", "දෂ්ට කළ තැනට මත්පැන් පෙවීම", "රෝගියා කලබල වීමෙන් හෘද ස්පන්දනය වැඩි වී විෂ සිරුර පුරා වේගයෙන් පැතිරෙන බැවින් සන්සුන්ව තැබිය යුතුය."),
        q("සර්ප දෂ්ටනයකදී විෂ පැතිරීම වැළැක්වීමේ සාම්ප්‍රදායික වැරදි මතයක් වන කිසිසේත්ම නොකළ යුතු භයානක ක්‍රියාව කුමක්ද?", "දෂ්ට කළ ස්ථානයට ඉහළින් තදින් ලේ බැමි (Tourniquets) යෙදීම", "රෝගියා සන්සුන් කිරීම", "ආධාරක තබා අත නිශ්චල කිරීම", "රෝහලට රැගෙන යාම", "තදින් ලේ බැමි යෙදීමෙන් රුධිර සංසරණය ඇණහිට අදාළ අවයවය කුණු වී කපා ඉවත් කිරීමට සිදුවිය හැක."),
        q("සර්පයෙකු දෂ්ට කළ ස්ථානය පිහියකින් කැපීම හෝ මුඛයෙන් විෂ උරා බීම නොකළ යුත්තේ මන්ද?", "පටක හා ස්නායුවලට හානි වී විෂ සිරුරට වේගයෙන් උරා ගැනීමට හා ආසාදන ඇතිවීමට හේතු වන බැවින්", "සර්පයා නැවත පැමිණෙන නිසා", "ලේ ගැලීම නතර වන නිසා", "එය සාර්ථක ප්‍රතිකර්මයක් නිසා", "කැපීමෙන් හා උරා බීමෙන් ගැඹුරු පටක හානි සිදුවන අතර ප්‍රථමාධාරකරුටද විෂ ශරීරගත විය හැක."),
        q("සර්පයෙකු දෂ්ට කළ අතක් හෝ පාදයක් නිශ්චල කර තැබිය යුතු නිවැරදි උස මට්ටම කුමක්ද?", "හෘද මට්ටමට පහළින් හෝ හෘද මට්ටමේ තබාගත යුතුය", "හෘද මට්ටමට වඩා ඉතා ඉහළින් ඔසවා තැබීම", "හිසට ඉහළින් තැබීම", "නවා තද කර තැබීම", "අවයවය හෘද මට්ටමට පහළින් තැබීමෙන් විෂ හෘදය දෙසට ගමන් කිරීමේ වේගය පාලනය වේ."),
        q("ආහාර හෝ විදේශීය ද්‍රව්‍යයක් ශ්වාසනාලයේ සිරවීමෙන් හුස්ම හිරවීම (Choking) සිදුවූ වැඩිහිටියෙකුට මුලින්ම දිය යුතු ප්‍රතිකාරය කුමක්ද?", "රෝගියා ඉදිරියට නමා පිට මැදට අත්ලෙන් තද පහර 5ක් ගැසීම (5 Back Blows)", "වතුර වීදුරුවක් පෙවීම", "බත් ගුලියක් ගිල්ලවීම", "බිම පෙරළීම", "උරහිස් තල දෙක අතර මැදට තදින් එල්ල කරන පහර 5 මගින් පෙනහලුවල පීඩනය වැඩි වී සිරවූ ද්‍රව්‍යය ඉවතට පනී."),
        q("පිටට පහර දීමෙන් පසුත් ශ්වසන මාර්ගයේ අවහිරතාව පහව නොගියහොත් වැඩිහිටියෙකුට යොදන උදර තෙරපුම් ක්‍රමය කුමක්ද?", "හයිම්ලික් උපාමාරුව (Heimlich Maneuver / Abdominal Thrusts)", "CPR ක්‍රමය", "සෝදිසි ඉරියව්ව", "මුඛයෙන් හුස්ම දීම", "රෝගියාගේ පිටුපසින් සිට බඩවැල දෙසට ඉහළට හා ඇතුළට තදින් තෙරපුම් 5ක් යෙදීම හයිම්ලික් ක්‍රමයයි."),
        q("ගර්භණී කාන්තාවකගේ හෝ අධික ස්ථුල පුද්ගලයෙකුගේ උගුරේ යමක් සිරවී හුස්ම හිරවූ විට උදරය වෙනුවට තෙරපිය යුත්තේ කොතැනටද?", "පපුව මැදට තෙරපුම් ලබාදීම (Chest Thrusts)", "බඩට තදින් ගැසීම", "පාදවලින් එසවීම", "හිසට තට්ටු කිරීම", "ගර්භණී හෝ ස්ථුල අයට උදර තෙරපුම් අනතුරුදායක බැවින් පපුව මැදට පීඩනය (Chest thrusts) යොදයි."),
        q("මාස 12ට අඩු ළදරුවෙකුගේ උගුරේ යමක් සිරවී හුස්ම හිරවූ විට ලබාදිය යුතු නිවැරදි ප්‍රථමාධාරය කුමක්ද?", "පෙරබාහුව මත ළදරුවා මුණින්තලා කර හිස පහතට සිටින සේ තබා පිටට තට්ටු 5ක් සහ පපුව තෙරපුම් 5ක් දීම", "උදරය තදින් එබීම", "ළදරුවා උඩුබැලි අතට තබා කටට ඇඟිලි දැමීම", "කකුල් දෙකෙන් අල්ලා උඩුයටිකුරු කිරීම", "ළදරුවාගේ හිස පහතට සිටින සේ පෙරබාහුව මත රඳවා පිටට තට්ටු 5ක් හා පපුවට ඇඟිලි දෙකකින් තෙරපුම් 5ක් මාරුවෙන් මාරුවට දිය යුතුය."),
        q("ජලයේ ගිලුණු පුද්ගලයෙකු ගොඩට ගත් සැනින් නොකළ යුතු අනවශ්‍ය ක්‍රියාව කුමක්ද?", "උදරය ඔබමින් පෙනහලුවල ඇති ජලය ඉවත් කිරීමට උත්සාහ කිරීම", "හුස්ම ගැනීම පරීක්ෂා කිරීම", "තෙත ඇඳුම් ඉවත් කිරීම", "උණුසුම් කිරීම", "පෙනහලුවල ජලය ඉවත් කිරීමට උත්සාහ කිරීමෙන් වමනය ගොස් ශ්වසන මාර්ගය තවදුරටත් අවහිර විය හැක."),
        q("ජලයේ ගිලී සිහිසුන්ව හුස්ම නොගන්නා පුද්ගලයෙකුට ගොඩගත් වහාම ආරම්භ කළ යුතු ප්‍රතිකාරය කුමක්ද?", "කෘත්‍රිම ශ්වසනය ලබාදීම සහ CPR ක්‍රියාවලිය ආරම්භ කිරීම", "රෝගියා අව්වේ තැබීම", "බඩට පයින් ගැසීම", "වෛද්‍යවරයා එනතුරු බලා සිටීම", "ඔක්සිජන් නොමැතිව මොළය මියයාම වැළැක්වීමට වහාම මුඛයෙන් හුස්ම දීම හා පපුව තෙරපීම කළ යුතුය."),
        q("තෙල් හෝ ග්‍රීස් ගිනි ගැනීමකදී (Class F / Kitchen Fire) ගින්න නිවීම සඳහා ජලය නොදැමිය යුත්තේ මන්ද?", "උතුරන තෙල් සමග ජලය වාෂ්ප වී ගිනිදැල් හා තෙල් පිපිරී විසිරී යන බැවින්", "ජලයෙන් තෙල් සවිමත් වන නිසා", "ජලය නොගැලපෙන දියරයක් නිසා", "දුම වැඩි වන නිසා", "උණුසුම් තෙල් මතට ජලය දැමූ විට ජලය ක්ෂණිකව වාෂ්ප වී ගිනිදැල් ප්‍රචණ්ඩ ලෙස පැතිර යයි."),
        q("ක්‍රීඩකයෙකුගේ හිසට එල්ල වූ ප්‍රබල පහරකින් පසු තාවකාලිකව මොළයේ ක්‍රියාකාරිත්වය අඩපණ වීම හඳුන්වන්නේ කෙසේද?", "මොළය සෙලවීම හෙවත් කම්පනය (Concussion)", "අංශභාගය", "හිසේ උළුක්කුව", "ස්නායු බිඳීම", "හිසට පහරක් වැදී කරකැවිල්ල, මතකය නැතිවීම හෝ සිහිමද ගතිය ඇතිවීම Concussion වේ."),
        q("ක්‍රීඩකයෙකුට මොළය සෙලවීමේ (Concussion) ලක්ෂණ ඇතිවූ විට කණ්ඩායම් පුහුණුකරු අනුගමනය කළ යුතු අනිවාර්ය නීතිය කුමක්ද?", "ක්‍රීඩකයා වහාම ක්‍රීඩාවෙන් ඉවත් කළ යුතු අතර එදින නැවත ක්‍රීඩා කිරීමට ඉඩ නොදිය යුතුය", "විනාඩි 5ක විවේකයකින් පසු පිටියට යැවීම", "වේදනා නාශක දී දිගටම ක්‍රීඩා කරවීම", "කිසිදු පියවරක් නොගැනීම", "මොළය සෙලවුණු ක්‍රීඩකයෙකු වහාම ක්‍රීඩාවෙන් ඉවත් කර වෛද්‍ය පරීක්ෂාවකට යොමු කළ යුතුය."),
        q("දිගු දුර ධාවකයන්ගේ කෙණ්ඩේ ඉදිරිපස ටිබියා අස්ථිය ආශ්‍රිතව හටගන්නා වේදනාකාරී ආබාධය හඳුන්වන්නේ කෙසේද?", "ෂින් ස්ප්ලින්ට් ආබාධය (Shin Splints)", "ටෙනිස් එල්බෝ", "ඇකිලීස් ආබාධය", "දණහිස් උළුක්කුව", "දෘඪ පොළොවේ දිවීම හා අධික වෙහෙස නිසා ටිබියා අස්ථිය වටා ඇති පටක ප්‍රදාහය වීම Shin Splints වේ."),
        q("ටෙනිස් ක්‍රීඩකයන්ගේ වැළමිටේ පිටත ප්‍රදේශයේ කණ්ඩරා ආසාදනය වීමෙන් හටගන්නා ආබාධය කුමක්ද?", "ටෙනිස් එල්බෝ ආබාධය (Tennis Elbow)", "ගොල්ෆර්ස් එල්බෝ", "ෂින් ස්ප්ලින්ට්", "උරහිස් විස්ථාපනය", "වැළමිටේ පාර්ශ්වික එපිකොන්ඩයිල ප්‍රදේශයේ කණ්ඩරා ආසාදනය වීම Tennis Elbow වේ."),
        q("විලුඹට ඉහළින් පිහිටි ශරීරයේ විශාලතම හා ශක්තිමත්ම කණ්ඩරාව අධික වෙහෙස නිසා ආසාදනය වීම කුමක්ද?", "ඇකිලීස් කණ්ඩරා ප්‍රදාහය (Achilles Tendinitis)", "පැටෙල්ලා ආබාධය", "උළුක්කුව", "බන්ධනී ඉරීම", "විලුඹ අස්ථිය හා කෙණ්ඩ පේශිය යා කරන ඇකිලීස් කණ්ඩරාවේ වේදනාව Achilles Tendinitis වේ."),
        q("විවෘත අස්ථි බිඳීමකදී සමෙන් පිටතට නෙරා ඇති අස්ථි කොටස සම්බන්ධයෙන් ප්‍රථමාධාරකරු කළ යුත්තේ කුමක්ද?", "අස්ථි කොටස සම තුළට තල්ලු නොකර විෂබීජහරණය කළ රෙදිකඩකින් වසා නිශ්චල කිරීම", "අස්ථිය සම තුළට තද කර දැමීම", "අස්ථිය කඩා ඉවත් කිරීම", "අයිස් කෙළින්ම අස්ථිය මත තැබීම", "එළියට ආ අස්ථි කොටස් ඇතුළට තල්ලු කළහොත් විෂබීජ ඇතුළට ගොස් දරුණු ආසාදන හටගනී."),
        q("රිය අනතුරකට ලක් වූ අයෙකුගේ කොඳු ඇට පෙළට හානි වී ඇතැයි සැක කරන විට රෝගියා ඔසවා ගෙන යා යුතු නිවැරදි ක්‍රමය කුමක්ද?", "කොඳු නාරටිය නොනැමෙන සේ තද ලෑල්ලක් (Spine Board) මත ලොග් රෝල් ක්‍රමයෙන් තබා රැගෙන යාම", "අත් පා වලින් ඔසවාගෙන යාම", "පුටුවක වාඩි කරවා ගෙන යාම", "රෝගියා ඇවිද්දවීම", "සුෂුම්නාවට හානි වී අංශභාගය ඇතිවීම වැළැක්වීමට හිස, බෙල්ල හා කොන්ද එකම සරල රේඛාවක තබාගත යුතුය."),
        q("හිස සහ බෙල්ල ප්‍රදේශයට අනතුරක් සිදුවූ රෝගියෙකුගේ ශ්වසන මාර්ගය විවෘත කිරීමට හිස පිටුපසට නොනවා යොදා ගන්නා ක්‍රමය කුමක්ද?", "යටි හනුව එසවීමේ ක්‍රමය (Jaw-Thrust Maneuver)", "හිස පිටුපසට ඇල කිරීම", "මුඛය පිඹීම", "බෙල්ල කරකැවීම", "බෙල්ලේ කශේරුකාවලට හානි නොවී ශ්වසන මාර්ගය විවෘත කිරීමට Jaw-thrust ක්‍රමය භාවිත කරයි."),
        q("ප්‍රථමාධාරයේදී විෂබීජ නාශකයක් යොදා තුවාලයක් පිරිසිදු කළ යුතු නිවැරදි දිශානතිය කුමක්ද?", "තුවාලයේ මැද සිට පිටත දෙසට වක්‍රාකාරව පිස දැමීම", "පිටත සිට තුවාලයේ මැදට", "එහා මෙහා අතුල්ලා දැමීම", "කැමති ඕනෑම පැත්තකට", "තුවාලයේ මැද සිට පිටතට පිස දැමීමෙන් පිටත ඇති විෂබීජ තුවාලය තුළට ඇතුළු වීම වැළකේ."),
        q("සිරුර තුළට විදේශීය වස්තුවක් (වීදුරු කටුවක්, පිහියක් හෝ යකඩ ඇණයක්) ඇනී ඇති විට කළ යුතු ප්‍රථමාධාරය කුමක්ද?", "ඇනී ඇති වස්තුව නොගලවා එය වටා ආධාරක තබා සෙලවීම වළක්වා රෝහල්ගත කිරීම", "වස්තුව වහාම ඇද ගලවා ඉවත් කිරීම", "වස්තුව තවදුරටත් ඇතුළට තල්ලු කිරීම", "තුවාලය ගැඹුරට සේදීම", "ඇනී ඇති වස්තුව ඇද දැමුවහොත් එයින් වැසී තිබූ ප්‍රධාන රුධිර නාල විවෘත වී දැඩි රුධිර වහනයකින් රෝගියා මිය යා හැක."),
        q("අත් පා ඇඟිල්ලක් හෝ අවයවයක් කපා වෙන් වූ (Amputation) අවස්ථාවක වෙන් වූ කොටස රෝහලට ගෙන යා යුතු නිවැරදි ක්‍රමය කුමක්ද?", "පිරිසිදු පොලිතින් බෑගයක දමා මුද්‍රා කර එම බෑගය අයිස් සහිත ජල බඳුනක බහා රැගෙන යාම", "කෙළින්ම අයිස් කැට තුළ එබීම", "උණු වතුරේ දැමීම", "විෂබීජ නාශක දියරයක දැමීම", "අවයවය තෙත් නොවී වියළි ප්ලාස්ටික් බෑගයක දමා එය අයිස් වතුර බඳුනක තැබීමෙන් පටක ජීවීව පවතී."),
        q("වෙන් වූ අවයව කොටසක් සෘජුවම අයිස් කැට තුළ නොදැමිය යුත්තේ මන්ද?", "සෘජු ශීතල නිසා සෛල හා පටක මියගොස් නැවත බද්ධ කිරීමේ හැකියාව විනාශ වන බැවින්", "අයිස් දියවන නිසා", "අවයවය දියවන නිසා", "කිසිදු ගැටලුවක් නැත", "සෘජුව අයිස් කැටවල ගැටීමෙන් පටක හිම පිළිස්සුම්වලට ලක්ව මියයයි."),
        q("අකුණු අනතුරකට ලක් වූ පුද්ගලයෙකු ඇල්ලීම ප්‍රථමාධාරකරුට ආරක්ෂිතද?", "ඔව්, අකුණු සැර වැදුණු සිරුරේ විදුලිය රැඳී නොපවතින බැවින් වහාම CPR ලබාදිය හැක", "නැත, ඇල්ලූ සැණින් ප්‍රථමාධාරකරුට විදුලි සැර වදී", "දින 3ක් යන තුරු ඇල්ලිය නොහැක", "ජලය ගැසූ පසු පමණක් ඇල්ලිය හැක", "අකුණු සැර වැදුණු පසු සිරුරේ කිසිදු විදුලි ආරෝපණයක් ඉතිරි නොවන බැවින් ප්‍රමාදයකින් තොරව ප්‍රථමාධාර දිය යුතුය."),
        q("බඹරුන් හෝ දෙබරුන් දෂ්ට කළ විට සම තුළ ඉතිරි වූ විස කටුව ඉවත් කළ යුතු වඩාත් ආරක්ෂිත ක්‍රමය කුමක්ද?", "බැංකු කාඩ්පතක් හෝ පිහි තලයක මොට පැත්තක් ආධාරයෙන් සම මතුපිටින් සූරා ඉවත් කිරීම", "ඇඟිලි තුඩුවලින් අල්ලා මිරිකා ඇදීම", "කටුව තවදුරටත් සම තුළට තල්ලු කිරීම", "ගින්දරෙන් පිලිස්සීම", "මොට දාරයකින් සූරා දැමීමෙන් විස මල්ල මිරිකී විස ඇතුළු වීම වළක්වා ගත හැක."),
        q("මීමැසි විස කටුවක් ඇඟිලි තුඩුවලින් තද කර ඇද නොගත යුත්තේ මන්ද?", "කටුව අග ඇති විස මල්ල තෙරපී වැඩිදුරටත් විස ශරීරගත වීම වැළැක්වීමට", "කටුව අස්ථිවලට වදින නිසා", "කටුව නැවත ජීවී වන නිසා", "කිසිදු හානියක් නැත", "ඇඟිලිවලින් මිරිකීමේදී කටුව පිටුපස ඇති විෂ ග්‍රන්ථිය මිරිකී සම්පූර්ණ විෂ ප්‍රමාණයම සිරුරට යයි."),
        q("පළිබෝධනාශක හෝ වස වර්ගයක් පානය කළ අයෙකුට ප්‍රථමාධාර ලබාදීමේදී කිසිසේත්ම නොකළ යුත්තේ කුමක්ද?", "බලහත්කාරයෙන් වමනය කරවීමට උත්සාහ කිරීම", "වහාම රෝහල්ගත කිරීම", "වස බෝතලය හෝ ලේබලය රැගෙන යාම", "ඇඳුම් ලිහිල් කිරීම", "වමනය කරවීමට යාමේදී පෙණහලුවලට වස කාන්දු වීම හා ආහාර මාර්ගය නැවත පිලිස්සීම සිදුවිය හැක."),
        q("පෙට්‍රල් හෝ භූමිතෙල් වැනි ඛනිජ තෙල් පානය කළ අයෙකු වමනය නොකරවිය යුත්තේ මන්ද?", "වාෂ්ප පෙනහලුවලට ඇතුළු වී රසායනික නියුමෝනියාව හටගත හැකි බැවින්", "තෙල් දිරවන නිසා", "වමනය නොයන නිසා", "කිසිදු හානියක් නැති නිසා", "ඛනිජ තෙල් වාෂ්ප ශ්වාසනාලය ඔස්සේ පෙණහලුවලට ගොස් මාරාන්තික රසායනික නියුමෝනියාව සාදයි."),
        q("රුධිරය වහනය වන තුවාලයකට යෙදූ පළමු වෙළුම් පටිය ලෙයින් තෙත් වූ විට කළ යුත්තේ කුමක්ද?", "පළමු වෙළුම ඉවත් නොකර ඒ මතින් තවත් පීඩන වෙළුමක් යෙදීම", "පළමු වෙළුම ගලවා විසි කිරීම", "තුවාලය සේදීම", "පීඩනය මුදා හැරීම", "පළමු වෙළුම ඉවත් කළහොත් සෑදී එන රුධිර කැටිය බිඳී ලේ ගැලීම යළිත් උග්‍ර වේ."),
        q("කම්පනය වළක්වා ගැනීමට හා රෝගියාගේ බිය දුරු කිරීමට ප්‍රථමාධාරකරු ලබාදිය යුතු මානසික සහනය කුමක්ද?", "රෝගියා අස්වැසීම හා ධෛර්යමත් කිරීම (Reassurance)", "රෝගියා බිය ගැන්වීම", "අනතුරේ බරපතළකම විස්තර කිරීම", "කෑගැසීම", "රෝගියා මානසිකව සන්සුන් කිරීමෙන් හෘද ස්පන්දනය පාලනය වී කම්පනයට පත්වීම වළකී."),
        q("ප්‍රථමාධාරකරු තමාගේම ආරක්ෂාව තහවුරු කරගැනීම සඳහා රුධිරය හා තරල ස්පර්ශ වීම වැළැක්වීමට පැළඳිය යුත්තේ කුමක්ද?", "විෂබීජහරණය කළ අත් මේස් (Gloves)", "ලෙදර් ජැකට්ටුවක්", "හිස්වැස්මක් පමණි", "සපත්තු පමණි", "HIV, හෙපටයිටිස් B වැනි රුධිරයෙන් බෝවන රෝගවලින් ආරක්ෂා වීමට අත්වැසුම් පැළඳීම අනිවාර්ය වේ."),
        q("ක්ලාන්තය (Fainting) ඇතිවීමට ආසන්න පුද්ගලයෙකු වාඩි කර හිස තැබිය යුතු වඩාත් සුදුසු ඉරියව්ව කුමක්ද?", "පුටුවක වාඩි කර හිස දණහිස් දෙක අතරට පහත් කිරීම", "හිස ඉහළට ඔසවා තැබීම", "සිටගෙන සිටීමට සැලැස්වීම", "පිටුපසට නැමීම", "හිස දණහිස් අතරට පහත් කිරීමෙන් මොළයට රුධිරය ගලා ඒම උත්තේජනය වේ."),
        q("ක්ලාන්ත වී බිම ඇද වැටුණු පුද්ගලයෙකුගේ සිහිය ඉක්මනින් ලබාගැනීමට කළ යුතු සරලම පියවර කුමක්ද?", "බිම උඩුබැලි අතට තබා දෙපා මඳක් ඉහළට ඔසවා තැබීම", "රෝගියාට නැගිටින්නැයි බල කිරීම", "මුහුණට තදින් පහර දීම", "උණුසුම් තේ පෙවීම", "දෙපා එසවීමෙන් මොළයට රුධිර සැපයුම කඩිනමින් යථා තත්ත්වයට පත් වේ."),
        q("රෝගියෙකුගේ ද්විතියික සමීක්ෂණයේදී (Secondary Survey) අසන AMPLE ඉතිහාසයේ M අකුර කුමක්ද?", "රෝගියා දැනට ලබාගන්නා ඖෂධ වර්ග (Medications)", "රෝගියාගේ මානසික මට්ටම", "රෝගියාගේ මාංශ පේශි", "ආහාර වේල", "AMPLE යනු Allergies, Medications, Past history, Last meal, Events leading up වේ."),
        q("AMPLE හි A අකුරෙන් විමසන්නේ රෝගියාගේ කුමන තොරතුරද?", "රෝගියාට ඇති අසාත්මිකතා (Allergies)", "වයස (Age)", "ක්‍රියාකාරිත්වය (Activity)", "පෙනුම (Appearance)", "රෝගියාට යම් ඖෂධ හෝ ආහාර අසාත්මිකතා ඇත්දැයි පරීක්ෂා කිරීම A අකුරෙන් අදහස් වේ."),
        q("ක්‍රීඩා පිටියේ හදිසි අනතුරක් වූ විට ප්‍රථමාධාර ලබාදීමෙන් පසු ක්‍රීඩකයාට ක්‍රීඩා කිරීමට අවසර දිය හැක්කේ කාගේ නිර්දේශයෙන්ද?", "සුදුසුකම් ලත් ක්‍රීඩා වෛද්‍යවරයෙකුගේ පරීක්ෂාවෙන් පසුව පමණි", "කණ්ඩායමේ නායකයාගේ", "ක්‍රීඩකයාගේම කැමැත්තෙන්", "ප්‍රේක්ෂකයන්ගේ ඉල්ලීමෙන්", "ක්‍රීඩකයාගේ ආරක්ෂාව තහවුරු කළ හැක්කේ වෛද්‍ය පරීක්ෂාවකින් පසුව පමණි."),
        q("අස්ථි බිඳීමකදී ආධාරක දැවති ගැටගැසිය යුත්තේ කොතැනටද?", "කැඩුණු ස්ථානයට ඉහළින් සහ පහළින් නිරෝගී කොටස්වලට පමණි", "කැඩුණු ස්ථානය හරහා කෙළින්ම", "සන්ධිය මැදට පමණි", "පාදයේ ඇඟිලිවලට", "කැඩුණු ස්ථානය මත ගැට ගැසීමෙන් වේදනාව හා පටක හානිය වැඩිවන බැවින් ඉහළින් හා පහළින් ගැටගසයි."),
        q("ප්‍රථමාධාර ලබාදීමේ ක්‍රියාවලිය අවසන් වන්නේ කුමන අවස්ථාවේදීද?", "රෝගියා සුදුසුකම් ලත් වෛද්‍යවරයෙකු හෝ ගිලන්රථ සේවකයන් භාරයට පත් කළ විට", "තුවාලය බැඳ අවසන් වූ විට", "රෝගියාට සිහිය ආ විට", "වේදනාව අඩු වූ විට", "ප්‍රථමාධාරකරුගේ වගකීම නිමවන්නේ රෝගියා වෛද්‍ය කාර්ය මණ්ඩලයට නිල වශයෙන් භාරදීමෙනි.")
    )
}
